// DecodeWire decodes a codingagent.v1 payload under closed-world rules: every
// object rejects a key outside its frozen set at every nesting depth, a
// duplicate key is an error rather than last-wins, and no error message ever
// quotes a rejected value.
func DecodeWire(data []byte) (*WireEnvelope, error) {
	ev, err := decodeWireEnvelope(data, "")
	if err != nil {
		return nil, err
	}
	return &ev, nil
}

